      SUBROUTINE EXPLORCC     DETERMINE BEGINNING AND END OF SECTION WHERE FITTING OCCURSCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2B.CIN'      INCLUDE 'DATA2D.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'ELM0F.CIN'      INCLUDE 'ELM4E.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM9.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM10F.CIN'      INCLUDE 'ELM14A.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'ELM23.CIN'      INCLUDE 'ELM24A.CIN'      INCLUDE 'ELM24B.CIN'      INCLUDE 'ELM31A.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'STEPT1.CIN'      INCLUDE 'VFLAG.CIN'CC     LOCAL VARIABLESC      INTEGER        NVSET(NPVAR)      EXTERNAL       IDATA      LOGICAL        CKKCC-------------------------------------------------------------------C      NUM = 1      NDIF = 1      TYP1 = 0      TOTROT = 0.0      TOTRA = 0.0      IP = 0      NDLEV = 0      NCT = 0      NCTV = 0      NCTE = 0      NCTC = 0      DRC = .FALSE.      NORD1 = -1      NUM14S = 0      NCT14S = 0      ATWORK = NUSE .EQ. 0      MKG = .FALSE.      VFLAG = .FALSE.      DO 5 J = 1, NPVAR    5 NVSET(J) = 0C      IF (NEL .LE. 0) GO TO 5300   10 I = ISTOR(NUM)      TYPE = IDATA(I)      IF (TYPE .LE. 0 .OR. TYPE .GE. 50) GO TO 5200      CALL SKETCH(NUM)      NCT = NCT + 1      CALL DEPICT      TYPEC = TYPE      IF (.NOT. ATWE) GO TO 5200C      IVA = 0C      IF (TYPE .EQ. 2) GO TO 200      IF (TYPE .EQ. 5) GO TO 500      IF (TYPE .EQ. 6) GO TO 600      IF (TYPE .EQ. 9) GO TO 900      IF (TYPE .EQ. 10) GO TO 1000      IF (TYPE .EQ. 14) GO TO 1400      IF (TYPE .EQ. 22) GO TO 2200      IF (TYPE .EQ. 23) GO TO 2300      IF (TYPE .EQ. 24) GO TO 2400      IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29) GO TO 2800      IF (TYPE .EQ. 31) GO TO 3100      IF (TYPE .EQ. 33) GO TO 3300      IF (TYPE .EQ. 37) GO TO 3700      GO TO 5000CC     2. -- POLE FACE ROTATIONC  200 CALL CHEK(CKK)      IF (.NOT. CKK) GO TO 5200      NUMS = NUM      NUM = NUM4      I = ISTOR(NUM)      TYPE = IDATA(I)      CALL SKETCH(NUM)      NVTYPE = NPARMS      DO 250 JV = 1, NVTYPE      IADR = I + JV  210 ISIG = IABS(TIE(IADR))      IF (ISIG .NE. 0 .AND. ISIG .LE. NPVAR) NVSET(ISIG) = ISIG      IF (ISIG .EQ. 100) THEN        IADR = IDATA(IADR)        GO TO 210      ENDIF      IF (ISIG .EQ. 99) THEN        ISIG = 0        DO 220 K = 1, NPVAR        ITEST = NVSET(K)        IF (ITEST .GE. 0) ISIG = ITEST  220   CONTINUE      ENDIF  240 IF (ISIG .NE. 0) IVA = 1  250 CONTINUE      NUM = NUMS      I = ISTOR(NUM)      TYPE = IDATA(I)      GO TO 5000CC     5. -- QUADRUPOLEC  500 IF (NMISRB .NE. 0) CALL AGENDR(1)      GO TO 5000CC     6. -- UPDATEC  600 IF (DATA(I+1) .NE. 0.0) GO TO 5100      IADR = I + IPTOJ(4)      NUPS = IDATA(IADR)      IF (NUPS .NE. 0) THEN        DO 620 NAL = 1, NUPS        IF (NAL .GT. 10) GO TO 620        NMIS = IDATA(IADR+NAL)        IMIS = ISTOR(NMIS)        TYT = INT(DATA(IMIS+7))        LFM = TYT/100        LTAB = MOD(TYT/10,10)        IF (LFM .EQ. 0 .OR. LFM .EQ. 2 .OR. LTAB .EQ. 1) GO TO 620        DO 610 J = 1, 6        IF (TIE(IMIS+J) .NE. 0) IVA = 1  610   CONTINUE  620   CONTINUE      ENDIF      GO TO 5100CC     9. -- REPEATC  900 NREP = IDATA(I+1)      CALL REPEAT1      IF (FLUSHL) GO TO 5300      GO TO 5200CC     10. -- FITTING CONSTRAINTSC 1000 IF (.NOT. ATWE) GO TO 5200      NCTC = NCT      DRC = .FALSE.      GO TO 5200CC     14. -- ARBITRARY MATRIXC 1400 IF (TYP1 .NE. 14) THEN        NUM14S = NUM        NCT14S = NCT      ENDIF      GO TO 5000CC     22. -- DEFINE REGISTER CONTENTSC 2200 IF (.NOT. DRC) CALL FIND10      GO TO 5200CC     23. -- ALGEBRAIC OPERATIONSC 2300 K1REG = IDATA(I+1)      K1TIE = TIE(I+1)      K2REG = IDATA(I+2)      K2TIE = TIE(I+2)      IOPN = IDATA(I+3)      JREG = IDATA(I+4)      JTIE = TIE(I+4)      CALL DEPEND      IF (FLUSHL) GO TO 5300      GO TO 5200CC     24. -- DEFINED SECTIONC 2400 JDEF = IDATA(I+1)      IF (JDEF .EQ. 3 .OR. JDEF .EQ. 4) THEN        NADDEF(1) = IDATA(I+2)        NADDEF(2) = IDATA(I+3)      ENDIF      CALL DEFINE      IF (FLUSHL) GO TO 5300      GO TO 5200CC     28. -- RBEND OR 29. -- SBENDC 2800 IF (NMISRB .NE. 0) CALL AGENDR(1)      GO TO 5000CC     31. -- POSITION MARKERC 3100 NMARKS = IDATA(I+1)      DRC = .FALSE.      CALL AGENDA(1)      GO TO 5200CC     33. -- STORAGE OF MATRIX ELEMENTC 3300 DRC = .FALSE.      GO TO 5200CC     37. -- ALIGNMENT MARKERC 3700 IADR = I + IPTOJ(4)      NUPS = IDATA(IADR)      IF (NUPS .NE. 0) THEN        DO 3720 NAL = 1, NUPS        IF (NAL .GT. 10) GO TO 3720        NMIS = IDATA(IADR+NAL)        IMIS = ISTOR(NMIS)        TYT = INT(DATA(IMIS+7))        LFM = TYT/100        LTAB = MOD(TYT/10,10)        IF (LFM .EQ. 0 .OR. LFM .EQ. 2 .OR. LTAB .EQ. 1) GO TO 3720        DO 3710 J = 1, 6        IF (TIE(IMIS+J) .NE. 0) IVA = 1 3710   CONTINUE 3720   CONTINUE      ENDIF      GO TO 5100CC     DO VARY CODESC 5000 CALL SKETCH(NUM)      NVTYPE = NV(TYPE)      IF (NVTYPE .EQ. 0) GO TO 5200      IF (LSTEP) THEN        IF (ISTEP .GE. I .AND. ISTEP .LE. I + NVTYPE) THEN          IF (NCTV .EQ. 0) THEN            NUMV = NUM            NCTV = NCT            IF (TYPE .NE. 30) NCTE = NCT          ENDIF        ENDIF      ENDIF      DO 5050 JV = 1, NVTYPE      IADR = I + IPTOJ(JV) 5010 ISIG = IABS(TIE(IADR))      IVARY = ISIG      IF (IVARY .NE. 0 .AND. IVARY .LE. NPVAR) IVARY = VSTOR(IVARY)      IF (IVARY .GE. 2 .AND. IVARY .LE. 50) VFLAG = .TRUE.      IF (ISIG .NE. 0 .AND. ISIG .LE. NPVAR) GO TO 5040      IF (ISIG .EQ. 100) THEN        IADR = IDATA(IADR)        GO TO 5010      ENDIF      IF (ISIG .EQ. 99) THEN        ISIG = 0        DO 5020 K = 1, NPVAR        REF = DATA(IADR + K)        IF (REF .GT. 0.5) ISIG = 1 5020   CONTINUE      ENDIF 5040 IF (ISIG .NE. 0) IVA = 1 5050 CONTINUEC 5100 IF (IVA .EQ. 0) GO TO 5200      IF (NCTE .NE. 0) GO TO 5200      IF (TYPE .NE. 30 ) NCTE = NCT      IF (NCTV .EQ. 0) THEN        IF (TYPE .NE. 14) THEN          NUMV = NUM          NCTV = NCT        ELSE          NUMV = NUM14S          NCTV = NCT14S          NCTE = NCT14S        ENDIF      ENDIFCC     ADVANCE TO NEXT ELEMENTC 5200 IF (MKG .AND. NUM .EQ. NMARKE) CALL AGENDA(2)      IF (ALGR .AND. NUM .EQ. NMISRE) CALL AGENDR(2)      NUM = NUM + NDIF      IF (.NOT. MKG .AND. NUSE .NE. 0 .AND. NUM .GT. NUSE) GO TO 5300      TYP1 = TYPE      IF (NUM .LE. NEL) GO TO 10 5300 CONTINUE      RETURN      END